files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  inline-size: 100dvi;
  block-size: 100dvb;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background-color: #5f0dee;
}

img {
  max-inline-size: 100%;
  max-block-size: 50vh;
  border-radius: 30px;
  object-fit: cover;
}

.container {
  position: relative;
}

.button {
  position: absolute;
  inset: -20px 0 0 -20px;
  z-index: 5;
  inline-size: 50px;
  block-size: 50px;
  border: none;
  padding-inline-start: 30px;
  background-color: transparent;
  transition: 0.4s linear;
  cursor: pointer;
}

.button::before {
  content: '';
  position: absolute;
  inset: 0;
  inline-size: 0;
  block-size: 0;
  border-inline-end: 20px solid transparent;
  border-block-start: 20px solid #ce1d5a;
}

.button::after {
  content: '';
  position: absolute;
  inset: 8px 0 0 8px;
  inline-size: 0;
  block-size: 0;
  border-inline-end: 20px solid transparent;
  border-block-start: 20px solid #000;
}

.button:hover::before,
.button:hover::after {
  opacity: 0.7;
}

.card {
  position: relative;
  transition: transform 1.5s ease-in-out;
  transform-style: preserve-3d;
  transform-origin: left center;
}

.front {
  z-index: 2;
  border-radius: 30px;
}

.animated {
  transform: rotateY(180deg);
}
